import static ai.unifiedprocess.demo.petclinic.database.tables.Tables.VET_SPECIALTIES;
import static org.jooq.impl.DSL.multiset;
import static org.jooq.impl.DSL.select;

/** Reads veterinarians and their alphabetically ordered specialties for UC-002. */
@Repository
@Transactional(readOnly = true)
public class VeterinarianRepository {

    private final DSLContext dsl;

    public VeterinarianRepository(DSLContext dsl) {
        this.dsl = dsl;
    }

    /** Fetches one bounded slice of the directory, including specialties in one query. */
    public Stream<Veterinarian> findPage(int offset, int limit) {
        return dsl.select(
                        VETS.ID,
                        VETS.FIRST_NAME,
                        VETS.LAST_NAME,
                        multiset(select(SPECIALTIES.NAME)
                                .from(VET_SPECIALTIES)
                                .join(SPECIALTIES).on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
                                .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
                                .orderBy(SPECIALTIES.NAME.asc()))
                                .convertFrom(specialties -> specialties.map(Record1::value1)))
                .from(VETS)
                .orderBy(VETS.LAST_NAME.asc(), VETS.FIRST_NAME.asc(), VETS.ID.asc())
                .offset(offset)
                .limit(limit)
                .fetch(Records.mapping(Veterinarian::new))
                .stream();
    }

    /** Counts directory entries for Vaadin's lazy data provider. */
    public int count() {
        return dsl.fetchCount(VETS);
    }
}
